// ─── Utility Functions ───
export function getCompaniesList() {
  return COMPANIES;
}

export function getQuestionsByCompany(companyId) {
  return COMPANY_QUESTIONS.filter(q => q.company === companyId);
}

export function getQuestionsByFilters({ company, role, stage, difficulty, search, frequencyMin, recentMonths }) {
  let filtered = [...COMPANY_QUESTIONS];

  if (company && company.length > 0) {
    const companySet = new Set(Array.isArray(company) ? company : [company]);
    filtered = filtered.filter(q => companySet.has(q.company));
  }
  if (role) filtered = filtered.filter(q => q.role === role);
  if (stage) filtered = filtered.filter(q => q.stage === stage);
  if (difficulty) filtered = filtered.filter(q => q.difficulty === difficulty);
  if (frequencyMin) filtered = filtered.filter(q => q.frequencyScore >= frequencyMin);
  if (recentMonths) {
    const cutoff = new Date();
    cutoff.setMonth(cutoff.getMonth() - recentMonths);
    filtered = filtered.filter(q => new Date(q.lastReported) >= cutoff);
  }
  if (search) {
    const s = search.toLowerCase();
    filtered = filtered.filter(q =>
      q.question.toLowerCase().includes(s) ||
      q.tags.some(t => t.toLowerCase().includes(s)) ||
      q.answer.toLowerCase().includes(s)
    );
  }

  return filtered;
}

export function getCompanyStats() {
  const stats = {};
  for (const c of COMPANIES) {
    const qs = COMPANY_QUESTIONS.filter(q => q.company === c.id);
    stats[c.id] = {
      total: qs.length,
      easy: qs.filter(q => q.difficulty === 'Easy').length,
      medium: qs.filter(q => q.difficulty === 'Medium').length,
      hard: qs.filter(q => q.difficulty === 'Hard').length,
      stages: [...new Set(qs.map(q => q.stage))],
    };
  }
  return stats;
}

export function getAllTags() {
  const tagSet = new Set();
  COMPANY_QUESTIONS.forEach(q => q.tags.forEach(t => tagSet.add(t)));
  return [...tagSet].sort();
}
